  let next = 0;
  for (let index = 0; index < b.length; index++) {
    if (sameEntry(a[next], b[index])) {next++; continue;}
    const between = next > 0 && a[next] && a[next].hunk !== a[next - 1].hunk && b[index].kind === ' ' && sameEntry(a[next], b[index + 1]);
