});

test('a file added whole in the compact signed form verifies against the hosted patch and nothing else', () => {
  const content = 'const a = 1;\nconst b = 2;\n';
  const header = 'diff --git a/src/n.js b/src/n.js\nnew file mode 100644\nindex 0000000..89abcde\n--- /dev/null\n+++ b/src/n.js\n@@ -0,0 +1,2 @@\n';
  const hosted = '@@ -0,0 +1,2 @@\n+const a = 1;\n+const b = 2;';
  const compact = (source = content, extra = {}) => ({sources: {head: {content: source}},
    files: [{path: 'src/n.js', status: 'added', patch: header, patch_body: 'head_source', head_source: 'head', ...extra}]});
  verifyPatches({snapshot: compact(), files: [live('src/n.js', 'added', hosted)]});
  verifyPatches({snapshot: compact('const a = 1;', {patch: header.replace('+1,2', '+1')}),
    files: [live('src/n.js', 'added', '@@ -0,0 +1 @@\n+const a = 1;\n\\ No newline at end of file')]});
  // The body differs from the head source, from GitHub's patch, or the marker has no source behind it.
  mismatch(() => verifyPatches({snapshot: compact('const a = 1;\nconst b = 3;\n'), files: [live('src/n.js', 'added', hosted)]}), 'src/n.js');
  mismatch(() => verifyPatches({snapshot: compact(), files: [live('src/n.js', 'added', hosted.replace('= 2', '= 9'))]}), 'src/n.js');
  mismatch(() => verifyPatches({snapshot: compact(content, {patch_body: 'other'}), files: [live('src/n.js', 'added', hosted)]}), 'src/n.js');
  mismatch(() => verifyPatches({snapshot: compact(content, {head_source: 'absent'}), files: [live('src/n.js', 'added', hosted)]}), 'src/n.js');
});

test('a verified chunked record holding a file added whole keeps its patch verification', async () => {
  const {chunkedFixture} = require('../test/chunked-fixture.cjs');
  const {issueReceipt, verifyReceipt} = require('./local-receipt.cjs');
  const compact = snapshot => {
    const file = snapshot.files.find(item => item.path === 'README.md');
    const lines = snapshot.sources[file.head_source].content.split('\n'); if (lines.at(-1) === '') lines.pop();
    Object.assign(file, {status: 'added', patch: `@@ -0,0 +1,${lines.length} @@\n`, patch_body: 'head_source'});
    delete file.base_source;
  };
  const f = await chunkedFixture({mutate: compact});
  const {record} = verifyReceipt(issueReceipt(f.issue), f.expected);
  assert.equal(record.snapshot.files.find(item => item.path === 'README.md').patch_body, 'head_source');
  const files = hostedFiles(record.snapshot);
  assert.ok(files.every(file => file.patch.length > 0));
  verifyPatches({snapshot: record.snapshot, files});
  const forged = structuredClone(record.snapshot);
  forged.sources[forged.files.find(item => item.path === 'README.md').head_source].content += 'extra line\n';
  mismatch(() => verifyPatches({snapshot: forged, files}), 'README.md');
});

test('a summarized lockfile is exempt from the patch comparison only when it is exactly the fixed placeholder', () => {
  const { LOCKFILE_PATCH } = require('./lockfile-summary.cjs');
  const item = (path, status, extra = {}) => ({path, status, patch: LOCKFILE_PATCH, lockfile: true, ...extra});
  const lock = (filename, status, patch) => live(filename, status, patch);
  // GitHub may omit the patch of a huge lockfile or give one: neither is compared, the summary is recomputed from the bytes.
  verifyPatches({snapshot: {files: [item('package-lock.json', 'modified')]}, files: [lock('package-lock.json', 'modified', undefined)]});
  verifyPatches({snapshot: {files: [item('package-lock.json', 'modified')]}, files: [lock('package-lock.json', 'modified', HUNK)]});
  mismatch(() => verifyPatches({snapshot: {files: [item('package-lock.json', 'modified')]}, files: [lock('package-lock.json', 'added', undefined)]}), 'package-lock.json');
  // A file that is not a lockfile, a changed placeholder or a missing patch for an ordinary file never gets the exemption.
  mismatch(() => verifyPatches({snapshot: {files: [item('src/a.js', 'modified')]}, files: [lock('src/a.js', 'modified', HUNK)]}), 'src/a.js');
  mismatch(() => verifyPatches({snapshot: {files: [item('yarn.lock', 'modified', {patch: HUNK})]}, files: [lock('yarn.lock', 'modified', HUNK)]}), 'yarn.lock');
  assert.throws(() => verifyPatches({snapshot: {files: [item('src/a.js', 'modified')]}, files: [lock('src/a.js', 'modified', undefined)]}), /incomplete/);
  assert.throws(() => verifyPatches({snapshot: {files: []}, files: [lock('package-lock.json', 'modified', undefined)]}), /incomplete/);
});

test('git function-name headings on hunk headers are ignored on both sides, and nothing else is', () => {
  const body = '\n context\n-old secret-free line\n+new line';
  const hunk = heading => `@@ -14,7 +14,7 @@${heading}${body}`;
  const signed = heading => snapshotOf(['tests/test_a.py', 'modified', `diff --git a/tests/test_a.py b/tests/test_a.py\nindex 1234567..89abcde 100644\n--- a/tests/test_a.py\n+++ b/tests/test_a.py\n${hunk(heading)}\n`]);
  for (const heading of [' import unittest', ' class Case(unittest.TestCase):', ' ## Section title', ' def run(): # @@ -1 +1 @@']) {
    verifyPatches({snapshot: signed(heading), files: [live('tests/test_a.py', 'modified', hunk(''))]});
    verifyPatches({snapshot: signed(''), files: [live('tests/test_a.py', 'modified', hunk(heading))]});
    verifyPatches({snapshot: signed(heading), files: [live('tests/test_a.py', 'modified', hunk(' other heading'))]});
  }
  // Two hunks, one with and one without a heading.
  const two = `${hunk(' import unittest')}\n@@ -40,2 +40,2 @@${body}`;
  verifyPatches({snapshot: snapshotOf(['a.py', 'modified', `${two}\n`]), files: [live('a.py', 'modified', `${hunk('')}\n@@ -40,2 +40,2 @@ def late():${body}`)]});
  // Line numbers, hunk bodies and body lines that merely look like headers still mismatch.
  mismatch(() => verifyPatches({snapshot: signed(' import unittest'), files: [live('tests/test_a.py', 'modified', hunk('').replace('-14,7', '-15,7'))]}), 'tests/test_a.py');
  mismatch(() => verifyPatches({snapshot: signed(' import unittest'), files: [live('tests/test_a.py', 'modified', hunk('').replace('+new line', '+new  line'))]}), 'tests/test_a.py');
  mismatch(() => verifyPatches({snapshot: signed(' import unittest'), files: [live('tests/test_a.py', 'modified', hunk('').replace('+new line', '+new line\n+extra'))]}), 'tests/test_a.py');
  const look = heading => snapshotOf(['a.py', 'modified', `@@ -1,2 +1,2 @@\n+@@ -9,9 +9,9 @@${heading}\n`]);
  mismatch(() => verifyPatches({snapshot: look(' x'), files: [live('a.py', 'modified', '@@ -1,2 +1,2 @@\n+@@ -9,9 +9,9 @@ y')]}), 'a.py');
  mismatch(() => verifyPatches({snapshot: signed(' import unittest'), files: [live('tests/test_a.py', 'modified', hunk('').replace('@@ -14,7 +14,7 @@', '@@ -14,7 +14,7'))]}), 'tests/test_a.py');
});

test('a patch mismatch classified as a source rejection carries the file name for the notice', () => {
  const error = new ReceiptPatchMismatch('src/a.js');
  assert.equal(error.path, 'src/a.js'); assert.equal(error.reason, 'source');
});

test('a patch rejection names the changed file to the caller, never a path taken from the receipt', async () => {
  const f = await fixture();
  const files = hostedFiles(f.snapshot);
  const pr = {changed_files: 1, base: {sha: f.snapshot.base_sha}, head: {sha: f.snapshot.head_sha, repo: {owner: {login: f.repo.owner}, name: f.repo.repo}}};
  const options = {github: f.github, repo: f.repo, pr, files, snapshot: f.snapshot, config: {readme: 'README.md', repository_policy: '.github/clouseau.md'}};
  const {screenSources} = require('./local-receipt.cjs');
  const forged = structuredClone(f.snapshot); forged.files[0].patch = `${forged.files[0].patch}\n+import './harmless'`;
  const named = [];
  assert.equal(await screenSources({...options, snapshot: forged, note: path => named.push(path)}), 'source');
  assert.deepEqual(named, [files[0].filename]);
  assert.equal(await screenSources({...options, snapshot: forged}), 'source', 'the note is optional');
  const foreign = structuredClone(f.snapshot); foreign.files[0].path = 'secret/elsewhere.js';
  assert.equal(await screenSources({...options, snapshot: foreign, note: path => named.push(path)}), 'source');
  assert.deepEqual(named, [files[0].filename], 'a path that only the receipt names is not reported');
});

test('GitHub joining two hunks that git leaves one unchanged line apart is the same patch; nothing broader is', () => {
  const body = (from, to) => Array.from({length: to - from + 1}, (_, index) => ` line ${from + index}`);
  // Changes at old lines 4 and 12: seven unchanged lines between them, so `git diff` shows 3 + 3 and skips line 8.
  const first = ['@@ -1,6 +1,7 @@', ...body(1, 3), '-old four', '+new four', '+added', ...body(5, 7)];
  const second = ['@@ -9,6 +10,6 @@ heading', ...body(9, 11), '-old twelve', '+new twelve', ...body(13, 14)];
  const signed = `${GIT_HEADER}${[...first, ...second].join('\n')}\n`;
  const joined = ['@@ -1,14 +1,15 @@', ...first.slice(1), ' line 8', ...second.slice(1)].join('\n');
  const check = patch => verifyPatches({snapshot: snapshotOf(['src/a.js', 'modified', signed]), files: [live('src/a.js', 'modified', patch)]});
  check(joined);
  // The joining line is unchanged file content that no reviewer saw as part of the change; its text is not compared.
  check(joined.replace(' line 8', ' other'));
  const flaws = [
    joined.replace(' line 8', '+line 8'), joined.replace(' line 8', ' line 8\n line 8b'),
    joined.replace(' line 7\n line 8', ' line 7\n line 8\n line 8b').replace(' line 9', ' line 9b'),
    joined.replace(' line 3\n', ' line 3\n line 3b\n'), joined.replace(' line 8', ' line 8\n').replace('@@ -1,14', '@@ -2,14'),
    `${joined}\n line 15`, joined.slice(0, joined.lastIndexOf('\n')), joined.replace('-old twelve', '-old twelve '), 'not a patch',
    ` line 8\n${joined}`,
  ];
  for (const flawed of flaws) mismatch(() => check(flawed), 'src/a.js');
  // A hunk-less signed patch and a hosted patch that is not hunks never join.
  mismatch(() => verifyPatches({snapshot: snapshotOf(['src/a.js', 'modified', `${GIT_HEADER}x\n`]), files: [live('src/a.js', 'modified', joined)]}), 'src/a.js');
  // The no-newline marker advances neither side.
  const marker = `${first.join('\n')}\n\\ No newline at end of file\n${second.join('\n')}`;
  const hosted = `${['@@ -1,14 +1,15 @@', ...first.slice(1)].join('\n')}\n\\ No newline at end of file\n line 8\n${second.slice(1).join('\n')}`;
  verifyPatches({snapshot: snapshotOf(['src/a.js', 'modified', `${GIT_HEADER}${marker}\n`]), files: [live('src/a.js', 'modified', hosted)]});
});

// Protected `local_review.binding: "diff"`: the change is bound, not the trees.
const {canonicalHunks, diffDigest} = require('./receipt-patch.cjs');
const DIFF = {binding: 'diff'};
const at = (old, now, text = '') => `@@ -${old},3 +${now},3 @@${text}\n a\n-b\n+B\n c`;

test('diff binding: hunk headers count only as @@, so lines added above the hunk on the base keep the receipt', () => {
  const signed = snapshotOf(['src/a.js', 'modified', `${GIT_HEADER}${at(10, 10, ' function run()')}\n`]);
  const result = verifyPatches({snapshot: signed, files: [live('src/a.js', 'modified', at(14, 14))], ...DIFF});
  assert.match(result.signed, /^[a-f0-9]{64}$/); assert.equal(result.signed, result.live);
  // The same offset without the binding is today's mismatch.
  mismatch(() => verifyPatches({snapshot: signed, files: [live('src/a.js', 'modified', at(14, 14))]}), 'src/a.js');
  // The digest is SHA-256 over the normalized entries and depends on nothing but them.
  assert.equal(diffDigest([{path: 'b', status: 'modified', previous: null, patch: '@@'}, {path: 'a', status: 'added', previous: null, patch: '@@'}]),
    diffDigest([{path: 'a', status: 'added', previous: null, patch: '@@'}, {path: 'b', status: 'modified', previous: null, patch: '@@'}]));
  assert.equal(diffDigest([]), require('node:crypto').createHash('sha256').update(JSON.stringify(['clouseau.receipt-diff.v1', []])).digest('hex'));
});

test('diff binding: any change to an added, removed or context line, or to whitespace, voids the receipt and names the file', () => {
  const signed = snapshotOf(['src/a.js', 'modified', `${GIT_HEADER}${at(1, 1)}\n`]);
  for (const changed of [at(1, 1).replace('+B', '+C'), at(1, 1).replace('-b', '-x'), at(1, 1).replace(' a', ' z'), at(1, 1).replace(' c', '  c'),
    `${at(1, 1)}\n d`, at(1, 1).replace('\n c', '')]) {
    mismatch(() => verifyPatches({snapshot: signed, files: [live('src/a.js', 'modified', changed)], ...DIFF}), 'src/a.js');
  }
  // A signed header that is not a known git header never matches.
  mismatch(() => verifyPatches({snapshot: snapshotOf(['src/a.js', 'modified', `prose\n${at(1, 1)}\n`]), files: [live('src/a.js', 'modified', at(1, 1))], ...DIFF}), 'src/a.js');
});

test('diff binding: a commit that adds a file, a removed file, a new status or another rename voids the receipt', () => {
  const signed = snapshotOf(['src/a.js', 'modified', at(1, 1)], ['src/b.js', 'modified', at(5, 5)]);
  verifyPatches({snapshot: signed, files: [live('src/a.js', 'modified', at(2, 2)), live('src/b.js', 'modified', at(9, 9))], ...DIFF});
  mismatch(() => verifyPatches({snapshot: signed, files: [live('src/a.js', 'modified', at(1, 1)), live('src/b.js', 'modified', at(5, 5)), live('src/c.js', 'added', at(1, 1))], ...DIFF}), 'src/c.js');
  mismatch(() => verifyPatches({snapshot: signed, files: [live('src/a.js', 'modified', at(1, 1))], ...DIFF}), 'src/b.js');
  mismatch(() => verifyPatches({snapshot: signed, files: [live('src/a.js', 'modified', at(1, 1)), live('src/b.js', 'added', at(5, 5))], ...DIFF}), 'src/b.js');
  assert.throws(() => verifyPatches({snapshot: signed, files: [live('src/a.js', 'modified', at(1, 1)), live('src/b.js', 'modified', undefined)], ...DIFF}), /Changed-file evidence is incomplete/);
  // A rename binds its previous path: the same rename keeps the receipt, another one voids it.
  const rename = from => `diff --git a/${from} b/src/new.js\nsimilarity index 90%\nrename from ${from}\nrename to src/new.js\n--- a/${from}\n+++ b/src/new.js\n${at(1, 1)}\n`;
  const renamed = {files: [{path: 'src/new.js', status: 'renamed', patch: rename('src/old.js'), base_source: 'old'}], sources: {old: {path: 'src/old.js'}}};
  verifyPatches({snapshot: renamed, files: [live('src/new.js', 'renamed', at(4, 4), {previous_filename: 'src/old.js'})], ...DIFF});
  mismatch(() => verifyPatches({snapshot: renamed, files: [live('src/new.js', 'renamed', at(4, 4), {previous_filename: 'src/other.js'})], ...DIFF}), 'src/new.js');
  // The digests themselves disagree when the signed previous path is not the rename GitHub reports.
  const lying = {...renamed, sources: {old: {path: 'src/elsewhere.js'}}};
  mismatch(() => verifyPatches({snapshot: lying, files: [live('src/new.js', 'renamed', at(4, 4), {previous_filename: 'src/old.js'})], ...DIFF}), 'src/new.js');
  const unsourced = {...renamed, sources: undefined};
  mismatch(() => verifyPatches({snapshot: unsourced, files: [live('src/new.js', 'renamed', at(4, 4), {previous_filename: 'src/old.js'})], ...DIFF}), 'src/new.js');
});

test('diff binding: GitHub joining two git hunks across one unchanged line is the same diff; any other run is not', () => {
  const two = '@@ -1,5 +1,5 @@ x\n a\n-b\n+B\n c\n d\n e\n@@ -9,5 +9,5 @@\n f\n g\n h\n-i\n+I\n j';
  const joined = '@@ -1,13 +1,13 @@\n a\n-b\n+B\n c\n d\n e\n JOIN\n f\n g\n h\n-i\n+I\n j';
  assert.equal(canonicalHunks(two), canonicalHunks(joined));
  assert.equal(canonicalHunks(joined), '@@\n a\n-b\n+B\n c\n d\n e\n@@\n f\n g\n h\n-i\n+I\n j');
  // Six or eight unchanged lines are not GitHub's join; leading and trailing runs of seven are not between two changes.
  assert.equal(canonicalHunks('@@\n-b\n c\n d\n e\n f\n g\n h\n-i'), '@@\n-b\n c\n d\n e\n f\n g\n h\n-i');
  assert.equal(canonicalHunks('@@\n-b\n c\n d\n e\n f\n g\n h\n i\n j\n-k'), '@@\n-b\n c\n d\n e\n f\n g\n h\n i\n j\n-k');
  const seven = Array.from({length: 7}, (_, index) => ` ${index}`).join('\n');
  assert.equal(canonicalHunks(`@@\n${seven}\n-b`), `@@\n${seven}\n-b`);
  assert.equal(canonicalHunks(`@@\n-b\n${seven}`), `@@\n-b\n${seven}`);
  assert.equal(canonicalHunks(`@@\n-b\n${seven}\n\\ No newline at end of file`), `@@\n-b\n${seven}\n\\ No newline at end of file`);
  verifyPatches({snapshot: snapshotOf(['src/a.js', 'modified', `${GIT_HEADER}${two}\n`]), files: [live('src/a.js', 'modified', joined)], ...DIFF});
});

test('diff binding: a summarized lockfile and a change that shows no text bind their path and status', () => {
  const {LOCKFILE_PATCH} = require('./lockfile-summary.cjs');
  const snapshot = {files: [{path: 'package-lock.json', status: 'modified', patch: LOCKFILE_PATCH, lockfile: true},
    {path: 'empty.txt', status: 'added', patch: 'diff --git a/empty.txt b/empty.txt\nnew file mode 100644\nindex 0000000..e69de29\n', head_source: 'e'}],
  sources: {e: {path: 'empty.txt', content: ''}}};
  const result = verifyPatches({snapshot, files: [live('package-lock.json', 'modified', '@@ -1 +1 @@\n-a\n+b'), live('empty.txt', 'added', undefined)], ...DIFF});
  assert.equal(result.signed, result.live);
  mismatch(() => verifyPatches({snapshot, files: [live('package-lock.json', 'removed', '@@'), live('empty.txt', 'added', undefined)], ...DIFF}), 'package-lock.json');
});

